// Shared owner identity + server-enforced MFA (AAL2) + append-only audit helper
// for Café Desk Supabase Edge Functions (owner-admin and owner-resign).

export const OWNER_EMAIL_DOMAIN = "CAFE-DESK-OWNER-V1|";

// OWNER-DIGEST-BEGIN (generated by tools/sync_owner_digest.py — do not edit by hand)
export const OWNER_EMAIL_SHA256 =
  "72f63f593e8b7db71539bdb0c9ed04567a072b946102b1f353a049870b9ba1bc";
// OWNER-DIGEST-END

const ALLOWED_MFA_METHODS = new Set([
  "totp",
  "mfa/totp",
  "webauthn",
  "passkey",
  "recovery_code",
]);

function decodeBase64UrlUtf8(segment) {
  const clean = String(segment || "").trim().replace(/-/g, "+").replace(/_/g, "/");
  if (!clean) return null;
  const pad = "=".repeat((4 - (clean.length % 4)) % 4);
  const raw = atob(clean + pad);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

export function decodeJwtClaims(jwt) {
  try {
    const parts = String(jwt || "").trim().split(".");
    if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) return null;
    const jsonText = decodeBase64UrlUtf8(parts[1]);
    if (!jsonText) return null;
    const parsed = JSON.parse(jsonText);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

export function hasVerifiedMfaAmr(amr) {
  if (!Array.isArray(amr) || amr.length === 0) return false;
  return amr.some((entry) => {
    const method = typeof entry === "string" ? entry : entry && typeof entry === "object" ? entry.method : "";
    return ALLOWED_MFA_METHODS.has(String(method || "").trim().toLowerCase());
  });
}

export async function ownerEmailDigestHex(email) {
  const clean = String(email || "").trim().toLowerCase();
  const digestBuf = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(OWNER_EMAIL_DOMAIN + clean),
  );
  return Array.from(new Uint8Array(digestBuf))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export async function isVerifiedOwnerEmail(email, configuredOwnerEmail = "") {
  const clean = String(email || "").trim().toLowerCase();
  if (!clean) return false;
  const explicit = String(configuredOwnerEmail || "").trim().toLowerCase();
  if (explicit) return clean === explicit;
  return (await ownerEmailDigestHex(clean)) === OWNER_EMAIL_SHA256;
}

export async function verifyOwnerMfaRequest({
  authHeader = "",
  adminClient,
  configuredOwnerEmail = "",
  configuredOwnerUserId = "",
}) {
  const header = String(authHeader || "");
  if (!header.startsWith("Bearer ")) {
    return {
      ok: false,
      status: 401,
      code: "AUTH_REQUIRED",
      error: "Owner login required.",
    };
  }
  const jwt = header.slice(7).trim();
  if (!jwt) {
    return {
      ok: false,
      status: 401,
      code: "AUTH_REQUIRED",
      error: "Owner login required.",
    };
  }

  // 1. Verify the token and resolve the current user through Supabase Auth.
  const { data: userData, error: userErr } = await adminClient.auth.getUser(jwt);
  const user = userData?.user;
  if (userErr || !user || !user.id) {
    return {
      ok: false,
      status: 401,
      code: "INVALID_SESSION",
      error: "Invalid or expired login session.",
    };
  }

  // 2. Decode the GoTrue-verified JWT claims and bind sub + role.
  const claims = decodeJwtClaims(jwt);
  if (
    !claims ||
    String(claims.sub || "") !== String(user.id) ||
    (claims.role !== undefined && claims.role !== "authenticated")
  ) {
    return {
      ok: false,
      status: 403,
      code: "INVALID_CLAIMS",
      error: "Session token claims do not match the authenticated user.",
    };
  }

  // 3. Verify owner identity (email digest, optional pinned UUID, optional server role claim).
  const emailOk = await isVerifiedOwnerEmail(user.email || "", configuredOwnerEmail);
  const pinnedUid = String(configuredOwnerUserId || "").trim().toLowerCase();
  const uidOk = !pinnedUid || String(user.id).trim().toLowerCase() === pinnedUid;
  const userRoleMeta = String(user.app_metadata?.cafedesk_role || "").trim();
  const jwtRoleMeta = String(claims.app_metadata?.cafedesk_role || "").trim();
  const roleOk =
    (!userRoleMeta || userRoleMeta === "owner") &&
    (!jwtRoleMeta || jwtRoleMeta === "owner");

  if (!emailOk || !uidOk || !roleOk) {
    return {
      ok: false,
      status: 403,
      code: "FORBIDDEN_NOT_OWNER",
      error: "Access denied: Only the verified Café Desk owner account can access this API.",
    };
  }

  if (typeof claims.exp === "number" && claims.exp * 1000 < Date.now() - 5000) {
    return {
      ok: false,
      status: 401,
      code: "AUTH_REQUIRED",
      error: "Session token has expired.",
    };
  }

  // 4. Enforce MFA assurance (AAL2) + verified factor + MFA AMR method (fail-closed).
  const aalOk = String(claims.aal || "") === "aal2";
  const amrOk = hasVerifiedMfaAmr(claims.amr);
  const factorsOk =
    Array.isArray(user.factors) &&
    user.factors.some((f) => f && f.status === "verified");

  if (!aalOk || !amrOk || !factorsOk) {
    return {
      ok: false,
      status: 403,
      code: "MFA_REQUIRED",
      error:
        "Multi-factor authentication (AAL2) is required for owner operations. " +
        "Verify your 6-digit authenticator code and try again.",
    };
  }

  return {
    ok: true,
    status: 200,
    user,
    claims,
    actor: {
      userId: String(user.id),
      email: String(user.email || "").trim().toLowerCase(),
      aal: "aal2",
    },
  };
}

export async function recordOwnerAudit(adminClient, actor, entry) {
  if (!adminClient || typeof adminClient.from !== "function" || !actor) {
    throw new Error("Audit log client and authenticated actor are required.");
  }
  const row = {
    actor_user_id: String(actor.userId || ""),
    actor_email: String(actor.email || ""),
    actor_aal: String(actor.aal || "aal2"),
    action: String(entry?.action || "owner_action"),
    target_type: String(entry?.targetType || ""),
    target_id: String(entry?.targetId || ""),
    detail: entry?.detail && typeof entry.detail === "object" ? entry.detail : {},
  };
  const { error } = await adminClient.from("owner_audit_log").insert(row);
  if (!error) return;
  const msg = String(error.message || "");
  throw new Error(`Audit log write failed: ${msg}`);
}
